const downloadEmbeddedPdf = (dataUrl, filename) => {
  try {
    const commaIndex = dataUrl.indexOf(',');
    if (commaIndex < 0) throw new Error('Format PDF embedded tidak valid.');

    const meta = dataUrl.slice(0, commaIndex);
    const base64 = dataUrl.slice(commaIndex + 1);
    const mimeMatch = meta.match(/^data:([^;]+);base64$/);
    const mimeType = mimeMatch ? mimeMatch[1] : 'application/pdf';

    const binary = window.atob(base64);
    const bytes = new Uint8Array(binary.length);

    for (let i = 0; i < binary.length; i += 1) {
      bytes[i] = binary.charCodeAt(i);
    }

    const blob = new Blob([bytes], { type: mimeType });
    const objectUrl = URL.createObjectURL(blob);

    const anchor = document.createElement('a');
    anchor.href = objectUrl;
    anchor.download = filename || 'Checklist_Diagnosis_10_Medan_UMKM.pdf';
    anchor.style.display = 'none';

    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();

    window.setTimeout(() => URL.revokeObjectURL(objectUrl), 1500);
    return true;
  } catch (error) {
    console.error('Checklist download error:', error);
    return false;
  }
};
