const getUtmParams = () => {
  if (typeof window === 'undefined') {
    return { utm_source: '', utm_medium: '', utm_campaign: '', utm_content: '', utm_term: '' };
  }

  const query = new URLSearchParams(window.location.search);
  return {
    utm_source: query.get('utm_source') || '',
    utm_medium: query.get('utm_medium') || '',
    utm_campaign: query.get('utm_campaign') || '',
    utm_content: query.get('utm_content') || '',
    utm_term: query.get('utm_term') || '',
  };
};

const appendUtmParams = (params) => {
  const utm = getUtmParams();
  Object.entries(utm).forEach(([key, value]) => params.append(key, value));
  return utm;
};

const trackLeadFunnelEvent = (eventName, payload = {}) => {
  if (typeof window === 'undefined' || !eventName) return;

  if (typeof window.fbq === 'function') {
    window.fbq('trackCustom', eventName, payload);
  }

  if (typeof window.gtag === 'function') {
    window.gtag('event', eventName, payload);
  }
};

const classifyWaitlistProspect = (scores, problem, target30) => {
  const numeric = scores.map((value) => Number(value));
  const average = numeric.reduce((sum, value) => sum + value, 0) / numeric.length;
  const problemIsClear = String(problem || '').trim().length >= 15;
  const targetIsClear = String(target30 || '').trim().length >= 10;

  if (average <= 6 && problemIsClear && targetIsClear) return 'Prospek Panas';
  if (average <= 9) return 'Prospek Hangat';
  return 'Prospek Dingin';
};

